-- Run once in the Supabase SQL editor. Public records are readable by everyone;
-- private queues and votes are protected by PostgreSQL row-level security.
create extension if not exists pgcrypto;
create type public.member_role as enum ('classmate','delegate','deputy','representative');
create type public.record_status as enum ('proposed','pending_review','approved','vetoed','in_progress','completed','blocked','open','closed','rejected','received','under_review','needs_clarification','action_planned','addressed','declined','draft');
create table public.profiles(id uuid primary key references auth.users on delete cascade, display_name text, role public.member_role not null default 'classmate', created_at timestamptz not null default now());
create table public.council_members(id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), display_name text not null, role text not null check(role in ('Class Representative','Deputy Class Representative','Class Delegate')), term_label text, term_start date, term_end date, responsibilities text not null default '', active boolean not null default true, created_at timestamptz not null default now());
create table public.announcements(id uuid primary key default gen_random_uuid(), title text not null, body text not null, category text, published boolean not null default false, author_id uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.minutes(id uuid primary key default gen_random_uuid(), title text not null, meeting_date date not null, attendees text not null default '', agenda text not null default '', summary text not null default '', proposals jsonb not null default '[]', decisions text not null default '', vetoes jsonb not null default '[]', assigned_responsibilities jsonb not null default '[]', follow_up text, published boolean not null default false, author_id uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.decisions(id uuid primary key default gen_random_uuid(), title text not null, description text not null, decision_type text not null check(decision_type in ('council_decision','class_wide_vote','administrative_matter')), status text not null default 'proposed', proposed_at timestamptz, decided_at timestamptz, vote_totals jsonb, responsible_member text, deadline date, progress_update text, blocked_reason text, veto_reason text, tie_break text, created_by uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opinions(id uuid primary key default gen_random_uuid(), category text not null, title text not null, description text not null, anonymous boolean not null default false, contact text, submitter_id uuid references auth.users, status text not null default 'received', assigned_to uuid references public.profiles(id), moderation_note text, public_response text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.petitions(id uuid primary key default gen_random_uuid(), title text not null, problem text not null, solution text not null, reason text not null, creator_id uuid not null references auth.users, support_count integer not null default 0, status text not null default 'pending_review', review_reason text, council_response text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.petition_support(petition_id uuid not null references public.petitions on delete cascade, user_id uuid not null references auth.users on delete cascade, created_at timestamptz not null default now(), primary key(petition_id,user_id));
create table public.polls(id uuid primary key default gen_random_uuid(), question text not null, description text not null default '', options jsonb not null, vote_type text not null check(vote_type in ('informal','formal')), opens_at timestamptz not null, closes_at timestamptz not null, eligible_voters text not null default 'verified_class_accounts', status text not null default 'draft', results_visibility text not null default 'after_close', decision_threshold text, created_by uuid references auth.users, created_at timestamptz not null default now(), check(closes_at>opens_at));
create table public.poll_votes(poll_id uuid not null references public.polls on delete cascade, user_id uuid not null references auth.users on delete cascade, option_index integer not null, created_at timestamptz not null default now(), primary key(poll_id,user_id));
create table public.audit_log(id bigint generated always as identity primary key, actor_id uuid references auth.users, action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.current_role() returns public.member_role language sql stable security definer set search_path=public as $$ select coalesce((select role from profiles where id=auth.uid()),'classmate'::member_role) $$;
create or replace function public.is_council() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role() in ('delegate','deputy','representative') $$;
create or replace function public.is_rep() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role()='representative' $$;
create or replace function public.log_change() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit_log(actor_id,action,entity_type,entity_id,details) values(auth.uid(),tg_op, tg_table_name, coalesce(new.id,old.id), case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end); return coalesce(new,old); end $$;
create trigger decision_audit after insert or update or delete on public.decisions for each row execute function public.log_change();
create trigger minutes_audit after insert or update or delete on public.minutes for each row execute function public.log_change();
create trigger announcement_audit after insert or update or delete on public.announcements for each row execute function public.log_change();
create or replace function public.count_support() returns trigger language plpgsql security definer set search_path=public as $$ begin update petitions set support_count=(select count(*) from petition_support where petition_id=new.petition_id) where id=new.petition_id; return new; end $$;
create trigger petition_support_count after insert or delete on public.petition_support for each row execute function public.count_support();
create or replace function public.lock_open_poll() returns trigger language plpgsql as $$ begin if old.status='open' and (new.options is distinct from old.options or new.question is distinct from old.question or new.vote_type is distinct from old.vote_type or new.opens_at is distinct from old.opens_at or new.closes_at is distinct from old.closes_at) then raise exception 'Open ballot configuration is locked; cancel and recreate it with an audit record.'; end if; return new; end $$;
create trigger poll_lock before update on public.polls for each row execute function public.lock_open_poll();
alter table profiles enable row level security; alter table council_members enable row level security; alter table announcements enable row level security; alter table minutes enable row level security; alter table decisions enable row level security; alter table opinions enable row level security; alter table petitions enable row level security; alter table petition_support enable row level security; alter table polls enable row level security; alter table poll_votes enable row level security; alter table audit_log enable row level security;
create policy profile_self_read on profiles for select to authenticated using(id=auth.uid() or is_council()); create policy council_profiles_manage on profiles for update to authenticated using(is_rep()) with check(is_rep());
create policy public_members_read on council_members for select using(active); create policy council_members_write on council_members for all to authenticated using(is_council()) with check(is_council());
create policy public_announcements_read on announcements for select using(published); create policy council_announcements_manage on announcements for all to authenticated using(is_council()) with check(is_council());
create policy public_minutes_read on minutes for select using(published); create policy council_minutes_manage on minutes for all to authenticated using(is_council()) with check(is_council());
create policy public_decisions_read on decisions for select using(true); create policy council_decisions_manage on decisions for all to authenticated using(is_council()) with check(is_council());
create policy opinion_submit on opinions for insert with check(true); create policy council_opinion_read on opinions for select to authenticated using(is_council()); create policy council_opinion_update on opinions for update to authenticated using(is_council()) with check(is_council());
create policy public_petition_read on petitions for select using(status in ('open','approved','rejected','closed')); create policy own_petition_read on petitions for select to authenticated using(creator_id=auth.uid()); create policy petition_submit on petitions for insert to authenticated with check(creator_id=auth.uid()); create policy council_petition_review on petitions for update to authenticated using(is_council()) with check(is_council());
create policy support_insert on petition_support for insert to authenticated with check(user_id=auth.uid()); create policy support_self_read on petition_support for select to authenticated using(user_id=auth.uid() or is_council());
create policy public_poll_read on polls for select using(status='open' or (status='closed' and results_visibility='after_close')); create policy council_poll_manage on polls for all to authenticated using(is_council()) with check(is_council());
create policy vote_own_insert on poll_votes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from polls where id=poll_id and status='open' and now() between opens_at and closes_at)); create policy vote_council_read on poll_votes for select to authenticated using(is_council());
create policy audit_council_read on audit_log for select to authenticated using(is_council());
-- Authenticated account bootstrap: trigger creates the least-privileged role.
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'name',''),'classmate'); return new; end $$;
create trigger auth_profile after insert on auth.users for each row execute function public.new_profile();
